class StrictDjangoObjectPermissions(DjangoObjectPermissions):
    perms_map = {
        **DjangoObjectPermissions.perms_map,
        'GET': ['%(app_label)s.view_%(model_name)s'],
        'OPTIONS': ['%(app_label)s.view_%(model_name)s'],
        'HEAD': ['%(app_label)s.view_%(model_name)s'],
    }

class ClinicalTrialRecordViewSet(viewsets.ModelViewSet):
    queryset = ClinicalTrialRecord.objects.all()
    serializer_class = ClinicalTrialRecordSerializer
    permission_classes = [permissions.IsAuthenticated, StrictDjangoObjectPermissions]
